// DE SPARQL-STAND: de endpointlijst-weergave.
//
// In ?sparql=<endpoint>-modus is het endpoint dé bron: de policylijst komt uit
// een SELECT (als skelet-graaf door dezelfde modelcode), details per kaart uit
// een CONSTRUCT. De KAARTEN zelf zijn niet anders dan in bestandsmodus — die
// komen hier als `children` binnen. Wat deze stand toevoegt is de chrome rond
// de TWEEFASIGE lading (viewer-bevroren/assets/doc.js, loadPolicyList):
//
//   fase 0  nog niets binnen        -> "SPARQL-endpoint bevragen…" + skelet.
//   fase 1  eerste beeld            -> per soort de eerste 60 titels staan er
//                                      als ECHTE kaarten; wat nog onbekend is
//                                      wordt ook als onbekend getoond, met een
//                                      skeleton-staart eronder als signaal "er
//                                      komt meer". `data-lijstfase="eerste"`
//                                      draagt die stand naar de kaartenlijst,
//                                      die er zijn tellers en filters op dempt.
//   fase 2  volledige index         -> alleen de kaarten.
//
// En het FOUTONDERSCHEID uit dezelfde functie: faalt de lijst zonder eerste
// beeld, dan de gewone endpoint-foutmelding (err.endpoint); faalt fase 2
// terwijl fase 1 stond, dan blijven die kaarten staan en komt de melding
// ernaast (err.fullIndex) — beter iets dan niets.
import { createEffect, createSignal, on, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  compatIndex, endpoint, fouten, laadStatus, lijstFase, lijstFout,
} from '../../stores/corpus.js';
import { tekst } from '../../stores/weergave.js';
import './sparql.css';

export interface SparqlStandProps {
  /** De gewone leesweergave (kaartenlijst). Zij verschilt niet van de
   *  bestandsmodus; alleen wat eromheen staat is hier anders. */
  children?: JSX.Element;
}

export function SparqlStand(props: SparqlStandProps) {
  const ep = () => endpoint() || '';
  const bezig = () => laadStatus() === 'laden';
  const reden = () => (fouten()[0]?.message) || '';
  // Het EERSTE BEELD is een stand van de lading, geen gevolgtrekking uit "staat
  // er toevallig nog een model". Dat laatste loog bij een wissel van een
  // bestandscorpus naar een falend endpoint: `laadCorpus` maakt het model niet
  // leeg bij het starten, dus zag de lezer fase 0 nooit en kreeg hij de
  // fase-2-fout te lezen voor een fase-0-fout (bevinding M-2).
  const eersteBeeld = () => lijstFase() === 'eerste';

  // …MAAR FASE 2 IS GEEN FASE 0. Zodra de volledige index binnenkomt zet
  // `laadPolicyLijst` eerst `setLijstFase(null)` en bouwt daarna pas het model
  // opnieuw; in dat gat is `lijstFase()` al null terwijl `laadStatus()` nog
  // 'laden' is. Op de conditie hierboven alleen viel het EERSTE BEELD daardoor
  // weg en stond er een seconde lang de fase-0-skeleton: gemeten op /brp-ap
  // secties 3 → 0 → 3, kaarten 60 → 0 → 60, en scrollY 1.200 → 0. Precies wat
  // de bevroren viewer níet doet — `renderLoading` laat de kaarten staan en
  // voert de voortgang via de statusregel, met de noot erbij dat wegvegen "een
  // flits lijst -> skeleton -> lijst" gaf (doc.js r.1124-1126).
  //
  // De poort is dus "is er in DEZE lading al een beeld geweest", niet "staat er
  // toevallig nog een model" — dat laatste zou bevinding M-2 terugbrengen (een
  // wissel van een bestandscorpus naar een falend endpoint liet het oude model
  // staan en fase 0 nooit zien).
  const [beeldGehad, zetBeeldGehad] = createSignal(false);
  createEffect(() => {
    if (lijstFase() === 'eerste') { zetBeeldGehad(true); return; }
    const s = laadStatus();
    // De lading is voorbij (klaar, fout of leeggemaakt): de volgende begint weer
    // bij fase 0.
    if (s !== 'laden') zetBeeldGehad(false);
  });
  // …EN EEN WISSEL TÍJDENS DE LADING telt ook als een nieuwe lading. Bij een
  // wissel naar een ander endpoint komt de status nooit uit 'laden' (`laadCorpus`
  // zet hem opnieuw op dezelfde waarde, dus zonder signaalwijziging), waardoor
  // de poort hierboven blijft staan en fase 0 werd overgeslagen — bevinding M-2
  // in een nieuwe jas (review-seat, bevinding I5). De ENDPOINT-wissel is het
  // signaal dat er wél is.
  //
  // `defer` mag hier wél, anders dan bij de fasewissel (bevinding C1): daar werd
  // de VORIGE waarde gelezen, en die zet Solid bij een uitgestelde eerste
  // doorloop niet. Hier wordt alleen op de wijziging gereageerd.
  createEffect(on(endpoint, () => zetBeeldGehad(false), { defer: true }));

  return (
    <section
      class="sparql-stand"
      aria-busy={bezig()}
      data-endpoint={ep() || undefined}
      data-lijstfase={lijstFase() || undefined}
      data-compat={compatIndex() ? 'true' : undefined}
    >
      {/* Fase 0 vervángt de weergave: de oude viewer zet renderLoading in de
          hoofdkolom, niet erboven. Zodra er een eerste beeld is, komen de
          kaarten in de plaats van het skelet. */}
      <Show
        when={bezig() && !eersteBeeld() && !beeldGehad()}
        fallback={props.children}
      >
        <p class="sparql-laden skel-melding" aria-live="polite">{tekst('load.queryEndpoint')}</p>
      </Show>

      {/* De skeleton-staart: geen tekst, alleen vorm. Hij zegt "er komt meer"
          op de plek waar die kaarten straks staan. */}
      <Show when={lijstFase() === 'eerste'}>
        <div class="sparql-staart" aria-hidden="true">
          <span class="skel" /><span class="skel" /><span class="skel" />
        </div>
      </Show>

      <Show when={laadStatus() === 'fout'}>
        <p class="src-err">
          {lijstFout() === 'volledigeIndex'
            ? tekst('err.fullIndex', { ep: ep(), msg: reden() })
            : tekst('err.endpoint', { ep: ep(), msg: reden() })}
        </p>
      </Show>
    </section>
  );
}
